package com.personalizedfriendsounds;

import lombok.Value;

@Value
public class PersonalizedFriendMapping
{
    String soundFile;
    String overheadText;
}

package com.personalizedfriendsounds;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import javax.inject.Inject;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

@Slf4j
@PluginDescriptor(
		name = "Personalized Friend Sounds",
		description = "Play custom sounds and overhead text for nearby friends"
)
public class PersonalizedFriendSoundsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private PersonalizedFriendSoundsConfig config;

	@Inject
	private PersonalizedFriendSoundEngine soundEngine;

	private final Set<String> seenPlayers = new HashSet<>();
	private int tickTimer = 5;

	@Override
	protected void startUp()
	{
		log.info("Personalized Friend Sounds started");
		log.info("Custom sound directory: {}",
				PersonalizedFriendSoundFileManager.getSoundDirectory().toAbsolutePath());
	}

	@Override
	protected void shutDown()
	{
		seenPlayers.clear();
		log.info("Personalized Friend Sounds stopped");
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.HOPPING
				|| event.getGameState() == GameState.LOGIN_SCREEN
				|| event.getGameState() == GameState.LOGIN_SCREEN_AUTHENTICATOR)
		{
			seenPlayers.clear();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() == ChatMessageType.LOGINLOGOUTNOTIFICATION)
		{
			String message = event.getMessage();
			if (message.contains(" has logged out."))
			{
				String name = normalizeName(message.replace(" has logged out.", ""));
				seenPlayers.remove(name);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (tickTimer > 0)
		{
			tickTimer--;
			return;
		}

		Map<String, PersonalizedFriendMapping> mappings = getMappings();
		if (mappings.isEmpty())
		{
			tickTimer = 5;
			return;
		}

		List<Player> players = client.getPlayers();
		if (players == null)
		{
			tickTimer = 5;
			return;
		}

		for (Player player : players)
		{
			if (player == null || player == client.getLocalPlayer() || player.getName() == null)
			{
				continue;
			}

			if (!player.isFriend())
			{
				continue;
			}

			String normalizedName = normalizeName(player.getName());

			if (seenPlayers.contains(normalizedName))
			{
				continue;
			}

			PersonalizedFriendMapping mapping = mappings.get(normalizedName);
			if (mapping == null)
			{
				continue;
			}

			seenPlayers.add(normalizedName);

			try
			{
				soundEngine.playClip(mapping.getSoundFile());
			}
			catch (Exception ex)
			{
				log.warn("Failed to play sound {} for player {}", mapping.getSoundFile(), player.getName(), ex);
			}

			String overhead = mapping.getOverheadText();

			if (overhead != null && !overhead.isBlank())
			{
				player.setOverheadText(overhead);
				player.setOverheadCycle(200);
			}
		}

		tickTimer = 5;
	}

	private Map<String, PersonalizedFriendMapping> getMappings()
	{
		Map<String, PersonalizedFriendMapping> mappings = new HashMap<>();
		String raw = config.userSoundMappings();

		if (raw == null || raw.isBlank())
		{
			return mappings;
		}

		for (String line : raw.split("\\r?\\n"))
		{
			String trimmed = line.trim();
			if (trimmed.isEmpty() || !trimmed.contains("="))
			{
				continue;
			}

			String[] parts = trimmed.split("=", 2);
			String username = normalizeName(parts[0]);
			String value = parts[1].trim();

			String soundFile;
			String overheadText = null;

			if (value.contains("|"))
			{
				String[] split = value.split("\\|", 2);
				soundFile = split[0].trim();
				overheadText = split[1].trim();
			}
			else
			{
				soundFile = value;
			}

			if (!username.isEmpty() && !soundFile.isEmpty())
			{
				mappings.put(username, new PersonalizedFriendMapping(soundFile, overheadText));
			}
		}

		return mappings;
	}

	private String normalizeName(String name)
	{
		if (name == null)
		{
			return "";
		}

		return name
				.replaceAll("\\P{Print}", " ")
				.replace('\u00A0', ' ')
				.trim()
				.toLowerCase();
	}

	@Provides
	PersonalizedFriendSoundsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PersonalizedFriendSoundsConfig.class);
	}
}

package com.personalizedfriendsounds;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("personalizedfriendsounds")
public interface PersonalizedFriendSoundsConfig extends Config
{
	@ConfigItem(
			keyName = "volume",
			name = "Volume",
			description = "Volume of sounds generated from plugin."
	)
	default int pluginVolume()
	{
		return 100;
	}

	@ConfigItem(
			keyName = "userSoundMappings",
			name = "Username sound mappings",
			description = "Format: username=sound.wav|optional text"
	)
	default String userSoundMappings()
	{
		return "";
	}

}

package com.personalizedfriendsounds;

import java.io.File;
import java.nio.file.Files;
import java.nio.file.Path;
import lombok.Getter;
import net.runelite.client.RuneLite;

public final class PersonalizedFriendSoundFileManager
{
    private static final String PLUGIN_DIR_NAME = "personalized-friend-sounds";
    private static final Path SOUND_DIR = RuneLite.RUNELITE_DIR.toPath().resolve(PLUGIN_DIR_NAME);

    private PersonalizedFriendSoundFileManager()
    {

    }

    public static SoundHandle resolveSound(String soundFile)
    {
        if (soundFile == null)
        {
            return null;
        }

        String trimmed = soundFile.trim();
        if (trimmed.isEmpty())
        {
            return null;
        }

        ensureSoundDirectoryExists();

        File externalFile = SOUND_DIR.resolve(trimmed).toFile();
        if (externalFile.exists() && externalFile.isFile())
        {
            return SoundHandle.forExternalFile(externalFile);
        }

        if (resourceExists(trimmed))
        {
            return SoundHandle.forBundledResource(trimmed);
        }

        return null;
    }

    public static Path getSoundDirectory()
    {
        ensureSoundDirectoryExists();
        return SOUND_DIR;
    }

    private static void ensureSoundDirectoryExists()
    {
        try
        {
            Files.createDirectories(SOUND_DIR);
        }
        catch (Exception ignored)
        {

        }
    }

    private static boolean resourceExists(String resourceName)
    {
        return PersonalizedFriendSoundFileManager.class.getResourceAsStream(resourceName) != null;
    }

    @Getter
    public static class SoundHandle
    {
        private final File file;
        private final String resourcePath;

        private SoundHandle(File file, String resourcePath)
        {
            this.file = file;
            this.resourcePath = resourcePath;
        }

        public static SoundHandle forExternalFile(File file)
        {
            return new SoundHandle(file, null);
        }

        public static SoundHandle forBundledResource(String resourcePath)
        {
            return new SoundHandle(null, resourcePath);
        }

        public boolean isExternalFile()
        {
            return file != null;
        }
    }
}

package com.personalizedfriendsounds;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.audio.AudioPlayer;

@Slf4j
@Singleton
public class PersonalizedFriendSoundEngine
{
    private final PersonalizedFriendSoundsConfig config;
    private final AudioPlayer audioPlayer;

    @Inject
    public PersonalizedFriendSoundEngine(
            PersonalizedFriendSoundsConfig config,
            AudioPlayer audioPlayer
    )
    {
        this.config = config;
        this.audioPlayer = audioPlayer;
    }

    public void playClip(String soundFile)
    {
        float gainDb = toGainDb(config.pluginVolume());

        try
        {
            PersonalizedFriendSoundFileManager.SoundHandle soundHandle =
                    PersonalizedFriendSoundFileManager.resolveSound(soundFile);

            if (soundHandle == null)
            {
                log.warn("Could not resolve sound '{}'", soundFile);
                return;
            }

            if (soundHandle.isExternalFile())
            {
                audioPlayer.play(soundHandle.getFile(), gainDb);
            }
            else
            {
                audioPlayer.play(
                        PersonalizedFriendSoundEngine.class,
                        soundHandle.getResourcePath(),
                        gainDb
                );
            }
        }
        catch (Exception e)
        {
            log.warn("Failed to play sound '{}'", soundFile, e);
        }
    }

    private float toGainDb(int volumePercent)
    {
        int clamped = Math.max(1, Math.min(100, volumePercent));
        float volume = clamped / 100f;
        return (float) Math.log10(volume) * 20f;
    }
}
